i think `has` should be used when we care only about the existence but not using the found item.
Here, we're using it if does exists.

So I would do:
```js
  let cachedFns = this[kRouteContext][kReplyCacheSerializeFns]?.get(schema)
  if (cachedFns != null) {
    const schema = cachedFns.get(cacheKey)
    if (schema != null) {
      return schema
    }
```

I would generate both from an array:
```js
for (const [statusCode, expectedContentLength] of [
  [205, '0'],
  [304, undefined]
]) {
  test(`code should handle ${statusCode}`, (t, done) => {
    t.plan(13)

    const fastify = Fastify()

    fastify.get(`/${statusCode}`, function (request, reply) {
      reply.status(statusCode)
      return null
    })

    fastify.get(`/undefined/${statusCode}`, function (request, reply) {
      reply.status(statusCode).send({ message: 'hello' })
    })

    fastify.get(`/stream/${statusCode}`, function (request, reply) {
      const stream = new Readable({
        read () {
          this.push(null)
        }
      })

      stream.on('end', () => {
        t.assert.ok('stream ended')
      })

      reply.status(statusCode).send(stream)
    })

    fastify.inject({
      method: 'GET',
      url: `/${statusCode}`
    }, (error, res) => {
      t.assert.ifError(error)
      t.assert.strictEqual(res.statusCode, statusCode)
      t.assert.strictEqual(res.payload, '')
      t.assert.strictEqual(res.headers['content-length'], expectedContentLength)
    })

    fastify.inject({
      method: 'GET',
      url: `/undefined/${statusCode}`
    }, (error, res) => {
      t.assert.ifError(error)
      t.assert.strictEqual(res.statusCode, statusCode)
      t.assert.strictEqual(res.payload, '')
      t.assert.strictEqual(res.headers['content-length'], expectedContentLength)
    })

    fastify.inject({
      method: 'GET',
      url: `/stream/${statusCode}`
    }, (error, res) => {
      t.assert.ifError(error)
      t.assert.strictEqual(res.statusCode, statusCode)
      t.assert.strictEqual(res.payload, '')
      t.assert.strictEqual(res.headers['content-length'], expectedContentLength)
      done()
    })
  })
}
```

I would centralize the conversion to the internal parser key, and reuse it in `add`, `hasParser` and `remove`.

For example:

```js
function toParserKey (contentType) {
  if (contentType === '*') {
    return ''
  }

  return new ContentType(contentType).toString()
}
```

For the current behavior where adding `'*'` twice replaces the previous catch-all parser, I would keep this exception in `existingParser()`:

```js
if (contentType === '*') {
  return false
}
```

